      var lines,unitsT,total,partials,priced; function calc(){ lines=Object.keys(ORD.cart).filter(function(s){return ORD.cart[s]>0;}).map(function(s){ var p=byS[s]||{sku:s,name:s}; var q=ORD.cart[s], cq=Number(p.carton_qty)||0, partial=cq>0&&q%cq!==0, price=P[s]; return {sku:s,p:p,qty:q,cartons:cq?Math.round(q/cq*100)/100:null,partial:partial,price:price,amount:price!=null?price*q:null,disc:p.discontinued&&p.disc_date&&p.disc_date<new Date().toISOString().slice(0,10)}; });
      unitsT=lines.reduce(function(s,l){return s+l.qty;},0); total=lines.reduce(function(s,l){return s+(l.amount||0);},0); partials=ORD.type==='sample'?0:lines.filter(function(l){return l.partial;}).length; priced=lines.every(function(l){return l.price!=null;}); } calc();
