        var TH='<tr><th></th><th>SKU</th><th>Type</th><th>Colour · size</th><th class="num" title="Units per carton. Whole cartons preferred.">Ctn qty</th><th class="num">Qty</th><th class="num">Price'+(showStock?' · stock':'')+'</th><th>Season · disc.</th></tr>';
